/*jslint browser: true, continue: true, eqeq: true, evil: true, plusplus: true, sloppy: true, vars: true, white: true */

classes.panels.AssetLibrary = function () {
	
	/* "imported" classes
		*/
		
	var Auth;
	var Func;
	var Dialog;
	var Lang;
	
	/* private properites
		*/
		
	var _instance = 			this;
	var _panel = 				null;
	var _parent = 				null;
	var _controller = 			null;
	var _uniquid = 				"FO" + classes.helpers.Func.uniquid();
	var _table = 				null;
	var _ingest = 				[];
	var _all = 					[];
	var _suid = 				"";
	var _name = 				"";
	var _key = 					"asset";
	var _init_filename = 		null;
	var _multiselect = 			true;
	var _filter = 				null;
	var _importer = 			{ use:false };
	var _sideload = 			{ use:false };
	var _selected = 			[];
	var _page = 				0;
	var _display = 				"normal";
	var _curated = 				false;
	var _paging = 				true;
	var _editable = 			true;
	var _image_list = 			[];
	var _image_loader = 		null;
	var _image_loader_index = 	-1;
	var _image_loader_loading = false;
	var _trigger_change_event = false;
	var _trigger_load_event = 	false;
	
	var _obj_upload = 			null;
	var _obj_delete = 			null;
	var _obj_sort = 			null;
	
	/* private methods
		*/
		
	function action (key, obj) {
		switch (key) {
			case "preview" :
				launchAsset(obj);
				break;
			case "del" :
				deleteAsset(obj);
				break;
			case "edit" :
				editAsset(obj);
				break;
		}
	}
	
	/* --- Sorting --- */
	function sortClick () {
		var provider = new Array();
		for (var i=0; i<_ingest.length; ++i) {
			provider.push({
				filename: _ingest[i].filename,
				index: _ingest[i].index
			});
		}
		var sw = StageProxy.width()-2;
		var sh = StageProxy.height()-2;
		var toolheight = 75;
		var gutter = 30;
		if (sw<768) {
			gutter = 0;
			toolheight += 75;
		}
		var maxwidth = sw-20-20-gutter-gutter;
		var maxheight = sh-40-20-20-40-gutter-gutter-toolheight;
		var colwidth = 110;
		var total = provider.length;
		var cols = Math.floor(maxwidth/colwidth);
		var rows = Math.ceil(total/cols);
		if (rows==1) cols = total;
		var dw = (cols*colwidth)+20;
		if (dw<680) {
			dw = 680;
		}
		var dh = (rows*colwidth);
		if (dh>maxheight) {
			dh = maxheight;
		}
		dw += 20+20;
		dh += 20+20+toolheight;
		Dialog.create({
			size: dw+"x"+dh,
			title: Lang.lookup("Sort Images"),
			content: classes.dialogs.ImageSort,
			init: {
				key: _key,
				suid: _suid,
				provider: provider
			},
			owner: this,
			options: [{
				label: Lang.lookup("Save"),
				func: saveImageIndices
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	function saveImageIndices (sorted) {
		_panel.screen(true);
		var indices = [];
		for (var i=0; i<_all.length; ++i) {
			indices[i] = i+","+i;
		}
		if (!sorted) {
			var editor = Dialog.last().classobj;
			var sorted = editor.indices();
		}
		for (var i=0; i<sorted.length; ++i) {
			var obj = sorted[i];
			indices[obj[0]] = obj.join(",");
		}
		indices = indices.join(";");
		Auth.send(this, onAssetData, {
			name: _name,
			suid: _suid,
			action: _key + "_reindex",
			indices: indices
		});
	}
	
	/* --- Uploads --- */
	function uploadClick () {
		Dialog.create({
			size: "600x*",
			title: Lang.lookup("Upload"),
			content: classes.dialogs.Upload,
			init: {
				dironly: _display=="category",
				key: _key,
				suid: _suid,
				name: _name,
				importer: _importer,
				sideload: _sideload
			},
			owner: this,
			options: [{
				label: Lang.lookup("Done"),
				func: uploadClose
			}]
		});
	}
	function uploadClose () {
		var editor = Dialog.last().classobj;
		if (editor.busy()==true) return;
		if (editor.uploaded()==0) return;
		_trigger_change_event = true;
		loadAssetData();
	}
	
	/* --- Image Lazy Loading Stuff --- */
	function cancelLazyLoading () {
		var obj = _image_list[_image_loader_index];
		if (obj) {
			var img = obj.find("img");
			img.off();
			clearInterval(_image_loader);
		}
	}
	function lazyError () {
		var obj = _image_list[_image_loader_index];
		var img = obj.find("img");
		img.attr("src", Func.getEmptyImgSrc());
	}
	function lazyLoaded () {
		var obj = _image_list[_image_loader_index];
		var img = obj.find("img");
		img.data("loaded", true);
		clearInterval(_image_loader);
		_image_loader = setTimeout(lazyLoadNext, 33);
	}
	function lazyLoadNext () {
		_image_loader_index = _image_loader_index + 1;
		if (_image_loader_index==_image_list.length) {
			_image_loader_index = _image_loader_index - 1
			_image_loader_loading = false;
			return;
		}
		_image_loader_loading = true;
		var obj = _image_list[_image_loader_index];
		var img = obj.find("img");
		img
			.attr("src", img.data("src"))
			.one('error', lazyError)
			.one('load', lazyLoaded)
			.each(Func.imgonload);
	}
	function lazyLoad (obj) {
		var img = obj.find("img");
		if (img.data("loaded")==false) {
			_image_list.push(obj);
			if (_image_loader_loading==false) {
				lazyLoadNext();
			}
		}
	}
	
	/* --- Video Snapshot Stuff --- */
	function checkForSnapshot(obj, row) {
		if (!_editable) {
			return;
		}
		var button = obj.find("button");
		button.click(function () {
			var sw = StageProxy.width()-2;
			var sh = StageProxy.height()-2;
			var toolheight = 75;
			var gutter = 30;
			if (sw<768) {
				gutter = 0;
				toolheight += 75;
			}
			var dims = row.dimensions.split("x");
			var asset_width = parseInt(dims[0], 10);
			var asset_height = parseInt(dims[1], 10);
			if ( isNaN(asset_width) || isNaN(asset_height) ) { // either no video info, no image info, so it will be a stage
				var asset_width = 480;
				var asset_height = 200;
			}
			var aspect = asset_width/asset_height;
			var maxwidth = sw-20-20-gutter-gutter;
			var maxheight = sh-40-20-20-40-gutter-gutter-toolheight;
			var dw = maxwidth;
			var dh = maxwidth/aspect;
			if (dh>maxheight) {
				dh = maxheight;
				dw = maxheight*aspect;
			}
			dw += 20+20;
			dh += 20+20+toolheight;
			Dialog.create({
				size: dw+"x"+dh,
				title: Lang.lookup("Capture Video Screenshot"),
				content: classes.dialogs.Snapshot,
				init: {
					suid: _suid,
					key: _key,
					name: _name,
					filename: row.filename
				},
				owner: this,
				options: [{
					label: Lang.lookup("Close"),
					func: updateSnapshot,
					param: obj
				}]
			});
		});
	}
	function updateSnapshot(obj) {
		var img = obj.find("img");
		img
			.off()
			.attr("src", Func.getEmptyImgSrc())
			.attr("src", img.data("src") + "&d" + new Date().getTime())
			.one('error', lazyError)
			.each(Func.imgonload);
	}
	
	/* --- Datatable Selection / Functions --- */
	function syncSelection () {
		for (var i=0; i<_ingest.length; ++i) {
			var row = _table.row(i);
			var node = $(row.node());
			var data = row.data();
			for (var j=0; j<_selected.length; ++j) {
				if ( data.filename == _selected[j].filename ) {
					if (node.hasClass("selected")==false) {
						row.select();
						change();
						break;
					}
				}
			}
		}
	}
	function change () {
		syncSelection();
		_obj_delete.addClass("Disabled").off();
		if (_selected.length>1) {
			_obj_delete.removeClass("Disabled").click(deleteAssets);
		}
		_instance.dispatch("onSelected");
	}
	function removeAll (redraw) {
		if (redraw==undefined) redraw = true;
		_selected = [];
		if (redraw) {
			change();
		}
	}
	function addByFilename (filename) {
		var doadd = true;
		var obj;
		for (var i=0; i<_ingest.length; ++i) {
			if (_ingest[i].filename==filename) {
				obj = _ingest[i];
				break;
			}
		}
		for (var i=0; i<_selected.length; ++i) {
			if (_selected[i].filename==filename) {
				_selected[i] = obj; // update
				doadd = false
				break;
			}
		}
		if (doadd) {
			_selected.push(obj);
			change();
		}
	}
	function removeByFilename (filename) {
		for (var i=0; i<_selected.length; ++i) {
			if (_selected[i].filename==filename) {
				_selected.splice(i, 1);
				change();
				break;
			}
		}
	}
	
	/* --- Asset Item Management --- */
	function launchAsset (obj) {
		var uri = Auth.basepath() + NAMESPACE + "-data/storage/" + (_suid==""?_key:_suid) + "/" + obj.filename;
			if (obj.service!=undefined) {
				uri ="http://" + obj.media_uri;
			}
		window.open(uri);
	}
	function editAsset (obj) {
		Dialog.create({
			size: "520x*",
			title: Lang.lookup("Edit File"),
			content: classes.dialogs.FileEditor,
			init: {
				label: obj.label,
				description: obj.description
			},
			owner: this,
			options: [{
				label: Lang.lookup("Save Changes"),
				func: editConfirm,
				param: obj
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	function editConfirm (obj) {
		var editor = Dialog.last().classobj;
		_trigger_change_event = true;
		_trigger_load_event = false;
		Auth.send(this, onAssetData, {
			name: _name,
			suid: _suid,
			action: _key + "_update",
			data: ([obj.filename, editor.label(), "null", "null", "null", editor.description()]).join("\t")
		});
	}
	function deleteAsset (obj) {
		Dialog.create({
			size: "520x*",
			title: Lang.lookup("delete_files_confirmation"),
			content: Lang.lookup("delete_files_confirmation_description"),
			owner: this,
			options: [{
				label: Lang.lookup("yes_delete"),
				func: deleteAssetConfirm,
				param: obj
			},{
				label: Lang.lookup("cancel")
			}]
		});
	}
	function deleteAssets () {
		Dialog.create({
			size: "520x*",
			title: Lang.lookup("delete_files_confirmation"),
			content: Lang.lookup("delete_files_confirmation_description"),
			owner: this,
			options: [{
				label: Lang.lookup("yes_delete"),
				func: deleteAssetsConfirm
			},{
				label: Lang.lookup("cancel")
			}]
		});
	}
	function deleteAssetConfirm (obj) {
		_panel.screen(true);
		_trigger_load_event = true;
		_trigger_change_event = true;
		Auth.send(this, onAssetData, {
			name: _name,
			suid: _suid,
			action: _key + "_delete",
			files: obj.filename
		});
	}
	function deleteAssetsConfirm () {
		_panel.screen(true);
		var files = [];
		for (var i=0; i<_selected.length; ++i) {
			files.push(_selected[i].filename);
		}
		files = files.join(",");
		_selected = [];
		_trigger_change_event = true;
		_trigger_load_event = true;
		Auth.send(this, onAssetData, {
			name: _name,
			suid: _suid,
			action: _key + "_delete",
			files: files
		});
	}
	
	/* --- Datatable Creation/Update --- */
	function filterIngest (redraw) {
		if (redraw==undefined) redraw = false;
		_ingest = [];
		for (var i=0; i<_all.length; ++i) {
			var obj = _all[i];
			if (_filter) {
				obj = _filter(obj);
				if (obj==false) continue;
			}
			_ingest.push(obj);
		}
		/* manbage sort
			*/
		_obj_sort.addClass("Disabled").off();
		if (_ingest.length>0) {
			_obj_sort.removeClass("Disabled").click(sortClick);
		}
		/*
			re-populate the grid
			*/
		if (_table!=null) {
			_table.clear();
			_table.rows.add(_ingest);
			_table.draw(redraw);
		}
		/*
			auto-select to start
			*/
		if ( _init_filename!=null && _init_filename!="" ) {
			addByFilename(_init_filename);
			_init_filename = null;
		}
		/*
			setup the selection
			*/
		change();
	}
	function onAssetData (success, data) {
		/*
			re-populate the grid
			*/
		_panel.screen(false);
		/*
			parse it all out
			*/
		_all = [];
		if (data) {
			var lines = data=="" ? [] : data.split("\n");
			var column_ids = ["filename", "label", "dimensions", "duration", "bytes", "description", "media_uri", "service"];
			for (var i=0; i<lines.length; ++i) {
				var line = lines[i];
				var values = line.split("\t");
				var obj = new Object();
				obj.index = i;
				for (var j=0; j<values.length; ++j) {
					var value = values[j];
					var column_id = column_ids[j];
					obj[column_id] = value || "";
				}
				_all.push(obj);
			}
		}
		/* broadcast loaded
			*/
		if (_trigger_load_event) {
			_trigger_load_event = false;
			_instance.dispatch("onAssetData");
		}
		/* filter the results
			*/
		filterIngest();
		/*
			trigger events
			*/
		if (_trigger_change_event) {
			_trigger_change_event = false;
			_instance.dispatch("onChanged");
		}
	}
	function loadAssetData () {
		_panel.screen(true);
		_trigger_load_event = true;
		Auth.send(this, onAssetData, {
			name: _name,
			suid: _suid,
			action: _key + "_list"
		});
	}
	function destroyCells () {
		$('#' + _uniquid).find("button").off();
	}
	function render () {
		
		/* add some html to start
			*/
		var parent = _parent || _panel.body();
		var xhtml = '';
			xhtml += '<div id="' + _uniquid + '" class="TablePanel">';
			xhtml += 	'<div class="Inner">';
		if (_editable) {
			xhtml += 		'<div class="Options">';
			xhtml += 			'<div class="Button Upload"><span class="glyphicon glyphicon-plus" aria-hidden="true"></span> ' + Lang.lookup("Add Media") + '</div>';
			xhtml += 			'<div class="Button Delete Secondary Disabled"><span class="glyphicon glyphicon-trash" aria-hidden="true"></span> ' + Lang.lookup("Delete") + '</div>';
		if ( _curated && !IS_MOBILE && !IS_TABLET && _key!="audio" && _key!="track" ) {
			xhtml += 			'<div class="Button Sort Secondary Disabled"><span class="glyphicon glyphicon-sort" aria-hidden="true"></span> ' + Lang.lookup("Sort") + '</div>';
		}
			xhtml += 			'<div class="Clear"></div>';
			xhtml += 		'</div>';
		}
			xhtml += 		'<table class="AssetTable' + (_curated?"Curated":"") + ' table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Clear"></div>';
			xhtml += '</div>';
		parent.html(xhtml);
		
		_obj_upload = parent.find("#" + _uniquid + " .Upload");
		_obj_delete = parent.find("#" + _uniquid + " .Delete");
		_obj_sort = parent.find("#" + _uniquid + " .Sort");
		
		_obj_upload.click(uploadClick);
		_obj_sort.click(sortClick);
		
		var cols = [
			{
				title: '',
				data: "index",
				width: 30,
				render: function ( data, type, row ) {
					return '<div style="text-align:center;cursor:pointer" class="DragIcon"><span class="glyphicon glyphicon-option-horizontal" aria-hidden="true"></span></div>';
				}
			},{
				title: "Preview",
				data: "filename",
				orderable: false,
				width: 100,
				render: function ( data, type, row ) {
					var ext = data.split(".").pop().toLowerCase();
					var xhtml = '<div style="text-align:center">';
					if (ext=="jpg"||ext=="jpeg"||ext=="jpe"||ext=="gif"||ext=="png") {
						var URI = Auth.basepath() + NAMESPACE + "-resample.php?q=";
						var query = "";
							query += (_suid==""?_key:_suid) + ":" + data + ":"; // the folder:file combo
							query += 100 + ":"; // the width
							query += 100 + ":"; // the height
							query += 1 + ":::1"; // the thumbnail it
						xhtml += '<div id="file-' + md5(data) + '" class="ImageObject">';
						xhtml += 	'<img src="' + Func.getEmptyImgSrc() + '" data-loaded="false" data-src="' + URI + query + '" width="100" height="100" />';
						xhtml += '</div>';
					} else if (ext=="mp3") {
						var uri = Auth.basepath() + NAMESPACE + "-data/storage/" + (_suid==""?_key:_suid) + "/" + row.filename;
						xhtml += '<div id="file-' + md5(data) + '" class="AudioObject" >';
						xhtml += 	'<div>';
						xhtml += 	'<audio class="listen" controls preload="none" src="' + uri + '"></audio>';
						xhtml += 	'</div>';
						xhtml += '</div>';
					} else if (ext=="mp4"||ext=="ogg"||ext=="webm"||ext=="mview") {
						var URI = Auth.basepath() + NAMESPACE + "-resample.php?q=";
						var query = "";
							query += (_suid==""?_key:_suid) + ":" + data + ".snapshot.jpg:"; // the folder:file combo
							query += 100 + ":"; // the width
							query += 100 + ":"; // the height
							query += 1 + ":::0"; // the thumbnail it
						xhtml += '<div id="file-' + md5(data) + '" class="ImageObject">';
						xhtml += 	'<button type="button" class="btn btn-default btn-sm">'
						xhtml += 		'<span style="font-size:1.5em;" class="glyphicon glyphicon-picture" aria-hidden="true"></span>';
						xhtml += 	'</button>';
						xhtml += 	'<img src="' + Func.getEmptyImgSrc() + '" data-loaded="false" data-src="' + URI + query + '" width="100" height="100" />';
						xhtml += '</div>';
					} else {
						xhtml += '<div id="file-' + md5(data) + '" class="FileObject">';
						xhtml += 	'<div style="margin: 0 auto;" class="file-icon file-icon-lg" data-type="' + ext + '"></div>';
						xhtml += '</div>';
					}
						xhtml += '</div>';
					return xhtml;
				}
			},{
				title: (_display=="normal"?"Label":"Filename"),
				data: "label",
				render: function ( data, type, row ) {
					if ( type === 'display' || type === 'filter' ) {
						data = data.split(" ").join("&nbsp;");
						if ( data=="" ) {
							data = '<i>' + Lang.lookup("Untitled") + "</i>";
						}
						var xhtml = '';
						if ( _editable && _display=="normal" ) {
							xhtml += 	'<a title="Edit">' + data + '</a>';
						} else {
							xhtml += 	'<span title="Edit">' + data + '</span>';
						}
						if ( row.description!=undefined && row.description!="" ) {
							xhtml += 	'<div class="AssetLabelDesc">';
							xhtml += 	row.description;
							xhtml += 	'</div>';
						}
						return xhtml;
					}
					return data;
				},
				responsivePriority: 1
			},{
				title: "Dimensions",
				data: "dimensions",
				type: "num",
				render: function ( data, type, row ) {
					var dims = data.split("x");
					if ( type === 'display' || type === 'filter' ) {
						return data=="x" ? "N/A" : data;
					}
					return parseInt(dims[0], 10) + parseInt(dims[1], 10);
				}
			},{
				title: "Duration",
				data: "duration",
				type: "num",
				render: function ( data, type, row ) {
					var duration = parseFloat(data);
					var kbps = ((parseFloat(row.bytes)*8)/duration)/1000;
					var timestamp = Func.secondsToTime(duration);
					if ( type === 'display' || type === 'filter' ) {
						return !isNaN(duration)&&duration>0 ? timestamp + " @ ~" + Math.round(kbps) + " kbps" : "N/A";
					}
					return duration;
				}
			},{
				title: "Size",
				data: "bytes",
				type: "num",
				render: function ( data, type, row ) {
					if ( type === 'display' || type === 'filter' ) {
						return Func.getByteString(data);
					}
					return parseFloat(data);
				}
			},{
				title: Lang.lookup("Actions"),
				data: "filename",
				orderable: false,
				render: function ( data, type, row ) {
					var xhtml = '';
					if ( _display=="normal" ) {
						xhtml += '<a data-suid="' + data + '" data-action="edit">Edit</a> / ';
					}
						xhtml += '<a data-suid="' + data + '" data-action="del">Delete</a>';
					if ( _display=="normal" ) {
						if (_key!="audio"&&_key!="track") {
							xhtml += ' / ';
							xhtml += '<a data-suid="' + data + '" data-action="preview">Preview</a>';
						}
					}
					return xhtml;
				},
				responsivePriority: 2
			}
		];
		var defs = [{
			targets: (_curated?1:0),
			createdCell: function (td, cellData, rowData, row, col) {
				var html = $(td);
				var id = "file-" + md5(cellData);
				var obj = html.find("#"+id);
				if (obj.hasClass("ImageObject")) {
					lazyLoad(obj);
					checkForSnapshot(obj, rowData);
				}
			}
		},{
			targets: (_curated?2:1),
			createdCell: function (td, cellData, rowData, row, col) {
				var html = $(td);
				var obj = html.find("a");
				obj.click(function (e) {
					editAsset(rowData);
					e.preventDefault();
					return false;
				});
			}
		},{
			targets: -1,
			createdCell: function (td, cellData, rowData, row, col) {
				var html = $(td);
				var obj = html.find("a");
				obj.click(function (e) {
					action($(this).data("action"), rowData);
					e.preventDefault();
					return false;
				});
			}
		}];
		var reorder = {
			update: false,
			dataSrc: 'index'
		};
		if (!_curated) {
			reorder = false;
			cols.shift();
		}
		if ( _display=="simple" ) {
			if (_key=="gallery"||_key=="image") {
				cols.splice(-3, 1);
			}
		} else if ( _display=="category" ) {
			if (_key=="gallery"||_key=="image") {
				cols.splice(-3, 1);
			}
		} else {
			if (_key=="audio"||_key=="track") {
				cols.splice(-4, 1);
			}
		}
		if (!_editable) {
			cols.pop();
			defs.pop();
			defs.pop();
		}
		var emptyTable = Lang.lookup("No Files Uploaded");
		if ( _display=="category" ) {
			emptyTable = Lang.lookup("No Files Uploaded Or Category Not Selected");
		}
		_table = $('#' + _uniquid + " table").DataTable( {
			stateSave: true,
			stateSaveCallback: function(settings,data) {
				localStorage.setItem( _uniquid, JSON.stringify(data) )
			},
			stateLoadCallback: function(settings) {
				return JSON.parse( localStorage.getItem( _uniquid ) )
			},
			language: {
				emptyTable: emptyTable
			},
			deferRender: true,
			preDrawCallback: destroyCells,
			rowReorder: reorder,
			info: _paging,
			searching: _curated==false,
			ordering: _curated==false,
			paging: _paging,
			order: ( _curated ? undefined : [[ 1, "asc" ]] ),
			responsive: {
				details: false
			},
			select: (_multiselect?'multi':'single'),
			data: [],
			columns: cols,
			columnDefs: defs
		});
		_table.on( 'row-reorder', function ( e, diff, edit ) {
			var indices = [];
			for (var i=0; i<diff.length; ++i) {
				var obj = diff[i];
				indices.push([obj.oldData, obj.newData]);
			}
			saveImageIndices(indices);
		});
		_table.on( 'page.dt', function () {
			var info = _table.page.info();
			_page = info.page;
		});
		_table.on( 'length.dt', function ( e, settings, len ) {
			var info = _table.page.info();
			_page = info.page;
		});
		_table.on( 'select', function ( e, dt, type, indexes ) {
			if ( type === 'row' ) {
				var filename = _table.rows( indexes ).data()[0].filename;
				if (filename=="") return;
				addByFilename(filename);
			}
		});
		_table.on( 'deselect', function ( e, dt, type, indexes ) {
			if ( type === 'row' ) {
				var filename = _table.rows( indexes ).data()[0].filename;
				if (filename=="") return;
				removeByFilename(filename);
			}
		});
		
		loadAssetData();
		
	}
	
	/* public methods
		*/
		
	this.option = function (key) {
		doOption(key);
	};
	this.uniquid = function (str) {
		if (str) {
			_uniquid = str;
		}
		return _uniquid;
	};
	this.importer = function (obj) {
		if (obj!=undefined) {
			_importer = obj;
		}
		return _importer;
	};
	this.sideload = function (obj) {
		if (obj!=undefined) {
			_sideload = obj;
		}
		return _sideload;
	};
	this.display = function (str) {
		if (str) {
			_display = str;
		}
		return _display;
	};
	this.editable = function (bool) {
		if (bool!=undefined) {
			_editable = bool;
		}
		return _editable;
	};
	this.curated = function (bool) {
		if (bool!=undefined) {
			_curated = bool;
		}
		return _curated;
	};
	this.paging = function (bool) {
		if (bool!=undefined) {
			_paging = bool;
		}
		return _paging;
	};
	this.key = function (str) {
		if (str) {
			_key = str;
		}
		return _key;
	};
	this.name = function (str) {
		if (str) {
			_name = str;
		}
		return _name;
	};
	this.suid = function (str) {
		if (str) {
			_suid = str;
		}
		return _suid;
	};
	this.multiselect = function (bool) {
		if (bool!==undefined) {
			_multiselect = bool;
		}
		return _multiselect;
	};
	this.filter = function (func) {
		_filter = func;
	};
	this.reload = function () {
		loadAssetData();
	};
	this.deselect = function (redraw) {
		removeAll(redraw);
	};
	this.refilter = function (redraw) {
		filterIngest(redraw);
	};
	this.getIngest = function (all) {
		return all===true ? _all : _ingest;
	};
	this.getSelected = function () {
		return _selected;
	};
	this.setSelected = function (str) {
		_init_filename = str;
	};
	this.controller = function (obj) {
		_controller = obj;
	};
	this.panel = function (obj) {
		_panel = obj;
	};
	this.parent = function (obj) {
		_parent = obj;
	};
	this.destroy = function () {
		cancelLazyLoading();
		destroyCells();
		_obj_delete.off();
		_obj_upload.off();
		_obj_sort.off();
		_table.off('length.dt');
		_table.off('page.dt');
		_table.off('row-reorder');
		_table.off('select');
		_table.off('deselect');
		_table.destroy(true);
	};
	this.initialize = function (obj) {
		Auth = classes.data.Auth;
		Lang = classes.data.Lang;
		Dialog = classes.components.Dialog;
		Func = classes.helpers.Func;
		for (var prop in obj) {
			this[prop](obj[prop]);
		}
		render();
	};
	
};

classes.panels.AssetLibrary.prototype = new EventDispatcher();

;
classes.panels.OrderStats = function () {
	
	/* "imported" classes
		*/
		
	var Admin;
	var SetList;
	var SiteBar;
	var Func;
	var Dialog;
	var Lang;
	var Auth;
	
	/* private properites
		*/
		
	var _instance = 			this;
	var _panel = 				null;
	var _controller = 			null;
	var _uniquid = 				"FO" + classes.helpers.Func.uniquid();
	
	var _breakdown_table = 		null;
	var _tax_table = 			null;
	var _obj_checks = 			null;
	var _obj_graph = 			null;
	var _obj_search = 			null;
	var _obj_start = 			null;
	var _obj_end = 				null;
	
	var _search_range = 		{ start:"", end:"" };
	var _breakdown = 			[];
	var _graph_array = 			[];
	var _graph_max = 			0;

	/* private methods
		*/
		
	function searchClick () {
		if ( $(this).hasClass("Disabled") ) return;
		_obj_search.addClass("Disabled");
		loadStatsData();
	}
	
	function datechange () {
		var changed = false;
		_obj_search.addClass("Disabled");
		var value = $(this).datepicker( "getDate" );
			var year = value.getFullYear();
			var month = value.getMonth();
			var day = value.getDate();
		if ( $(this).is(_obj_start) ) {
			var datestr = year + "/" + (month+1) + "/" + day;
			if ( datestr!=_search_range.start ) {
				changed = true;
				_search_range.start = datestr;
			}
		} else if ( $(this).is(_obj_end) ) {
			var datestr = year + "/" + (month+1) + "/" + day;
			if ( datestr!=_search_range.end ) {
				changed = true;
				_search_range.end = datestr;
			}
		}
		if ( changed ) {
			_obj_search.removeClass("Disabled");
		}
	}

	function onDataLoaded (success, data) {
		/* manage the tab panel
			*/
		_panel.screen(false);
		/*
			parse it all out
			*/
		_breakdown = [{
				name: "Subtotal",
				value: 0
			},{
				name: "Discount",
				value: 0
			},{
				name: "Shipping",
				value: 0
			},{
				name: "Handling",
				value: 0
			},{
				name: "Tax GST VAT",
				value: 0
			},{
				name: "Gross Sales",
				value: 0
			},{
				name: "Net Profit",
				value: 0
		}];
		var tax_lookup = {};
		var graph_lookup = {};
		var lines = !data || data=="" ? [] : data.split("\n");
		for (var i=0; i<lines.length; ++i) {
			var line = lines[i];
			var values = line.split("\t");
				var timestamp = values[0];
					timestamp_clean = timestamp.split("/").join("_");
				var region = values[1]
				var subtotal = Number(values[3]);
					subtotal = isNaN(subtotal) ? 0 : subtotal;
				var discount = Number(values[4]);
					discount = isNaN(discount) ? 0 : discount;
				var shipping = Number(values[5]);
					shipping = isNaN(shipping) ? 0 : shipping;
				var handling = Number(values[6]);
					handling = isNaN(handling) ? 0 : handling;
				var tax = Number(values[7]);
					tax = isNaN(tax) ? 0 : tax;
				var gross = Number(values[2]);
					gross = isNaN(gross) ? 0 : gross;
				var net = subtotal-discount;
			// do the breakdown table
			_breakdown[0].value += subtotal;
			_breakdown[1].value += discount;
			_breakdown[2].value += shipping;
			_breakdown[3].value += handling;
			_breakdown[4].value += tax;
			_breakdown[5].value += gross;
			_breakdown[6].value += net;
			// do the tax table
			if (!tax_lookup[region]) {
				tax_lookup[region] = 0;
			}
			tax_lookup[region] += tax;
			// do the graph stuff
			if (!graph_lookup[timestamp_clean]) {
				graph_lookup[timestamp_clean] = [0, 0, 0, 0, 0, 0, 0, 0];
			}
			graph_lookup[timestamp_clean][1] += subtotal;
			graph_lookup[timestamp_clean][2] += discount;
			graph_lookup[timestamp_clean][3] += shipping;
			graph_lookup[timestamp_clean][4] += handling;
			graph_lookup[timestamp_clean][5] += tax;
			graph_lookup[timestamp_clean][6] += gross;
			graph_lookup[timestamp_clean][7] += net;
		}
		_breakdown[1].value *= -1;
		/* clear the table, add new rows, then redraw
			*/
		_breakdown_table.clear();
		_breakdown_table.rows.add(_breakdown);
		_breakdown_table.draw(false);
		/*
			parse it all out again for taxes
			*/
		var tax_list = [];
		for (var region in tax_lookup) {
			tax_list.push({
				region: region,
				value: tax_lookup[region]
			});
		}
		/* clear the table, add new rows, then redraw
			*/
		_tax_table.clear();
		_tax_table.rows.add(tax_list);
		_tax_table.draw(false);
		/* clear the table, add new rows, then redraw
			*/
		_graph_array = [];
		_graph_max = 0;
		for (var timestamp_clean in graph_lookup) {
			var timestamp_bits = timestamp_clean.split("_");
			var timestamp_date = new Date(timestamp_bits[0], timestamp_bits[1]-1, timestamp_bits[2]);
			var day_arr = graph_lookup[timestamp_clean];
			for (var i=0; i<day_arr.length; ++i) {
				if (day_arr[i]>_graph_max) _graph_max = day_arr[i];
			}
			day_arr[0] = timestamp_date;
			_graph_array.push(day_arr);
		}
		_graph_max = _graph_max*1.1;
		drawGraph();
	}
	
	function drawGraph () {
		/* clear out the overlay
			*/
		var overlay = _obj_graph.find(".Overlay");
			overlay.empty();
		/* draw up the graph scales
			*/
		var thirdsindex = Math.round(_graph_array.length/3);
		var twothirdsindex = Math.round((_graph_array.length/3)*2);
		var dateleft = (_graph_array[0][0].getMonth()+1) + "/" + _graph_array[0][0].getDate() + "/" + _graph_array[0][0].getFullYear();
		var date3 = (_graph_array[thirdsindex][0].getMonth()+1) + "/" + _graph_array[thirdsindex][0].getDate() + "/" + _graph_array[thirdsindex][0].getFullYear();
		var date23 = (_graph_array[twothirdsindex][0].getMonth()+1) + "/" + _graph_array[twothirdsindex][0].getDate() + "/" + _graph_array[twothirdsindex][0].getFullYear();
		var TL = _obj_graph.find(".TL");
			TL.html(Math.round((_graph_max/3)*2));
		var CL = _obj_graph.find(".CL");
			CL.html(Math.round(_graph_max/3));
		var BL = _obj_graph.find(".BL");
			BL.html(dateleft);
		var BC = _obj_graph.find(".BC");
			BC.html(date3);
		var BR = _obj_graph.find(".BR");
			BR.html(date23);
		/* redraw the graph lines
			*/
		var lines = _obj_graph.find(".Lines");
			lines.empty();
		var width = Math.max(_graph_array.length, _obj_graph.width());
		var height = 197;
		var xstep = width/_graph_array.length;
		var graphs = ["statgraph-subtotal", "statgraph-discount", "statgraph-shipping", "statgraph-handling", "statgraph-tax", "statgraph-gross", "statgraph-net"];
		var colors = ["#000000", "#660066", "#33CC00", "#33CC00", "#FFCC00", "#0033FF", "#CC0000"];
		var ratio = height/_graph_max;
		for (var i=0; i<graphs.length; ++i) {
			var canvas = $('<canvas/>', { id: graphs[i] }).prop({ width: width, height: height });
			lines.append(canvas);
			var canvas = document.getElementById(graphs[i]);
			var context = canvas.getContext('2d');
			context.strokeStyle = colors[i];
			context.lineWidth = 2;
			context.beginPath();
			var xpos = 0;
			for (var j=0; j<_graph_array.length; ++j) {
				var column = _graph_array[j];
				var ypos = column[(i+1)];
					ypos = height-(ypos*ratio)-1;
				if (j==0) context.moveTo(xpos, ypos);
				context.lineTo(xpos, ypos);
				xpos += xstep;
			}
			context.stroke();
		}
		/* redraw the graph lines
			*/
		updateVisiblegraphs();
		
		/* we will do this another time
		// draw the hotspots
		var colwidth = 901/(columns.length-1);
		graph_display.overlay.createMovieClip("hotspots", null, 0, 0, MCV001.id);
		graph_display.overlay.hotspots._x = 0;
		graph_display.overlay.hotspots._x -= colwidth/2;
		for (var i=0; i<columns.length; ++i) {
			var column = columns[i];
			var hotspot = graph_display.overlay.hotspots.createMovieClip("hotspot"+i, null, i*colwidth, -1, Box.id, {
				_alpha: 0,
				width: colwidth,
				height: 202,
				linetype: [1, 0xcccccc, 100],
				filltype: [0xffffff, 100]
			});
			if (i==0) {
				hotspot._width = (colwidth/2)+1;
				hotspot._x += (colwidth/2)-1;
			}
			if (i==columns.length-1) {
				hotspot._width = (colwidth/2)+1;
			}
			hotspot.tiptext = column[0].getMonth() + "/" + column[0].getDate() + "/" + column[0].getFullYear();
			hotspot.breakdown = [{
				name: "stats subtotal",
				value: column[1]
			},{
				name: "stats discount",
				value: column[2]*-1
			},{
				name: "stats shipping",
				value: column[3]
			},{
				name: "stats handling",
				value: column[4]
			},{
				name: "stats tax",
				value: column[5]
			},{
				name: "stats gross",
				value: column[6]
			},{
				name: "stats net",
				value: column[7]
			}]
			hotspot.onRollOver = hotspot.onDragOver = function () {
				instance.breakdown_display.provider = this.breakdown;
				OrderPane.createToolTip(this.tiptext);
				this._alpha = 100;
			}
			hotspot.onRollOut = hotspot.onDragOut = function () {
				instance.breakdown_display.provider = instance.breakdown;
				OrderPane.killToolTip();
				this._alpha = 0;
			}
		}
		*/
	}
	
	function updateVisiblegraphs () {
		_obj_checks.each(function () {
			var checked = $(this).prop("checked");
			var key = $(this).data("key");
			if ( checked ) {
				$( "#"+key ).show();
			} else {
				$( "#"+key ).hide();
			}
		});
	}
	
	function loadStatsData () {
		_panel.screen(true);
		Auth.send(this, onDataLoaded, {
			action: "order_stats_search",
			start: _search_range.start,
			end: _search_range.end
		});
	}
	
	function resize () {
		drawGraph();
	}
	
	function render () {
		
		var today = new Date();
			var year = today.getFullYear();
			var month = today.getMonth();
			var day = today.getDate();
		var todayclean = new Date(year, month, day+1, 0, 0, 0, 0);
			var year = todayclean.getFullYear();
			var month = todayclean.getMonth();
			var day = todayclean.getDate();
		_search_range.end = year + "/" + (month+1) + "/" + day;
		var monthago = new Date(year, month, day-30, 0, 0, 0, 0);
			var year = monthago.getFullYear();
			var month = monthago.getMonth();
			var day = monthago.getDate();
		_search_range.start = (year) + "/" + (month+1) + "/" + day;
		
		var parent = _panel.body();
		var xhtml = '';
			xhtml += '<div id="' + _uniquid + '" class="StatsPanel">';
			xhtml += 	'<div class="Toolbar">';
			xhtml += 		'<div class="DateSelect Start"><label>' + Lang.lookup("Choose Start Date") + '</label><input type="input" value="' + _search_range.start + '" /></div>';
			xhtml += 		'<div class="DateSelect End"><label>' + Lang.lookup("Choose End Date") + '</label><input type="input" value="' + _search_range.end + '" /></div>';
			xhtml += 		'<div class="Button Disabled Search"><span class="glyphicon glyphicon-search" aria-hidden="true"></span> ' + Lang.lookup("Search") + '</div>';
			xhtml += 		'<div class="Clear"></div>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="GraphWrapper">';
			xhtml += 		'<div class="Graph">';
			xhtml += 			'<div class="Underlay">';
			xhtml += 				'<table><tbody><tr>';
			xhtml += 					'<td class="TL">&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>';
			xhtml += 				'</tr><tr>';
			xhtml += 					'<td class="CL">&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>';
			xhtml += 				'</tr><tr>';
			xhtml += 					'<td class="BL">&nbsp;</td><td class="BC">&nbsp;</td><td class="BR">&nbsp;</td>';
			xhtml += 				'</tr></tbody></table>';
			xhtml += 			'</div>';
			xhtml += 			'<div class="Overlay"></div>';
			xhtml += 			'<div class="Lines"></div>';
			xhtml += 		'</div>';
			xhtml += 		'<div class="Options">';
			xhtml += 			'<div class="Check"><input data-key="statgraph-subtotal" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Cart Total") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-discount" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Discount") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-shipping" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Shipping") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-handling" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Handling") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-tax" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Tax GST VAT") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-gross" type="checkbox" />&nbsp;&nbsp;' + Lang.lookup("Gross Sales") + '</div>';
			xhtml += 			'<div class="Check"><input data-key="statgraph-net" type="checkbox" checked />&nbsp;&nbsp;' + Lang.lookup("Net Profit") + '</div>';
			xhtml += 			'<div class="Clear"></div>';
			xhtml += 		'</div>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Clear"></div>';
			xhtml += 	'<div class="Left">';
			xhtml += 		'<table class="table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Right">';
			xhtml += 		'<table class="table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Clear"></div>';
			xhtml += '</div>';
		parent.html(xhtml);
		
		_obj_graph = parent.find("#" + _uniquid + " .Graph");
		_obj_search = parent.find("#" + _uniquid + " .Search");
		_obj_start = parent.find("#" + _uniquid + " .Start input");
		_obj_end = parent.find("#" + _uniquid + " .End input");
		_obj_checks = parent.find("#" + _uniquid + " .Check input");
		
		_obj_search.click(searchClick);
		_obj_start.change(datechange);
		_obj_end.change(datechange);
		_obj_checks.change(updateVisiblegraphs);
		
		_obj_start.datepicker({
			dateFormat: 'yy/mm/dd',
			changeMonth: true,
			changeYear: true
		});
		_obj_end.datepicker({
			dateFormat: 'yy/mm/dd',
			changeMonth: true,
			changeYear: true
		});
		
		/* create the datatable
			*/
		_breakdown_table = $('#' + _uniquid + " .Left table").DataTable( {
			searching: false,
			ordering: false,
			paging: false,
			info: false,
			responsive: {
				details: false
			},
			data: [],
			columns: [
				{
					title: "",
					data: "name"	
				},{
					title: Lang.lookup("Subtotal"),
					data: "value",
					width: "33%",
					render: function ( data, type, row ) {
						data = Number(data);
						if ( isNaN(data) ) data = 0;
						return Func.toFixed(data, 2);
					}	
				}
			]
		});
		_tax_table = $('#' + _uniquid + " .Right table").DataTable( {
			searching: false,
			ordering: false,
			paging: false,
			info: false,
			responsive: {
				details: false
			},
			data: [],
			columns: [
				{
					title: Lang.lookup("Tax Region"),
					data: "region"	
				},{
					title: Lang.lookup("Total Collected"),
					data: "value",
					width: "33%",
					render: function ( data, type, row ) {
						data = Number(data);
						if ( isNaN(data) ) data = 0;
						return Func.toFixed(data, 2);
					}	
				}
			]
		});
		
		/* start up our dataset
			*/
		loadStatsData();
		
		/* listen for stage events
			*/
		StageProxy.addEventListener("onResize", resize);

	}
	
	/* public methods
		*/
		
	this.option = function (key) {
		doOption(key);
	};
	this.panel = function (obj) {
		_panel = obj;
	};
	this.controller = function (obj) {
		_controller = obj;
	};
	this.destroy = function () {
		_obj_checks.off();
		_obj_search.off();
		_obj_start.datepicker( "destroy" );
		_obj_end.datepicker( "destroy" );
		_obj_start.off();
		_obj_end.off();
		_breakdown_table.destroy(true);
		_tax_table.destroy(true);
		StageProxy.removeEventListener("onResize", resize);
	};
	this.initialize = function () {
		Admin = classes.Admin;
		Auth = classes.data.Auth;
		Lang = classes.data.Lang;
		Dialog = classes.components.Dialog;
		Func = classes.helpers.Func;
		SetList = classes.components.SetList;
		SiteBar = classes.components.SiteBar;
		StageProxy = classes.StageProxy;
		render();
	};
	
};

