/*jslint browser: true, continue: true, eqeq: true, evil: true, plusplus: true, sloppy: true, vars: true, white: true */

classes.panels.Orders = function () {
	
	/* "imported" classes
		*/
		
	var Admin;
	var SetList;
	var SiteBar;
	var Func;
	var Dialog;
	var Lang;
	var Auth;
	
	/* private properites
		*/
		
	var _instance = 			this;
	var _panel = 				null;
	var _controller = 			null;
	var _ingest = 				[];
	var _table = 				null;
	var _obj_search = 			null;
	var _obj_export = 			null;
	var _uniquid = 				"global-order-table"; //"FO" + classes.helpers.Func.uniquid();
	var _column_ids = 			["orderid", "setid", "timestamp", "payment_type", "transactionid", "shipping_type", "discount_code", "full_name", "email_address", "phone_number", "shipping_address", "country", "postal_code", "state", "gross", "subtotal", "discount", "shipping", "handling", "tax", "taxrate", "prices_include_tax", "shipping_taxable", "handling_taxable", "comments", "payment_status", "payment_error", "refunded_minor"];
	var _trigger_change_event = false;
	
	var _search_range = 		{ start:"", end:"" };
	var _search_type = 			"";
	var _search_orderid = 		"";
	var _search_setid = 		"";
	var _search_name = 			"";
	var _search_email = 		"";
	
	/* private methods
		*/
	
	function action (key, obj) {
		switch (key) {
			case "output" :
				outputClick(obj);
				break;
			case "receipts" :
			case "paid" :
				$.ajax({url:Auth.basepath() + NAMESPACE + "-gateway.php", method:"POST", dataType:"json", data:{action:key==="paid" ? "payment_mark_paid" : "payment_receipts", order:obj.orderid, token:Auth.token()}})
					.done(function (result) { if (result.success) loadOrderData(); });
				break;
			case "del" :
				deleteClick(obj);
				break;
		}
	}
	
	function outputClick (obj) {
		window.open(Auth.basepath() + Auth.indexpath() + "?/order/" + obj.orderid + "/output/" + md5(obj.email_address) + "/");
	}
		
	function exportClick () {
		var csvtext = "";
		for (var i=0; i<_column_ids.length; ++i) {
			csvtext += '"' + Lang.lookup(_column_ids[i]) + '"';
			if (i<_column_ids.length-1) csvtext += ',';
			else csvtext += '\n';
		}
		for (var i=0; i<_ingest.length; ++i) {
			var row = _ingest[i];
			for (var j=0; j<_column_ids.length; ++j) {
				var value = row[_column_ids[j]];
				if (_column_ids[j]=="shipping_address") value = value.split("<[[BR]]>").join("\r");
				if (_column_ids[j]=="timestamp") {
					value = Number( value );
					var d = new Date( value );
					value = d.toLocaleDateString("en-US");
				}
				value = value.split('"').join("'");
				csvtext += '"' + value + '"';
				if (j<_column_ids.length-1) csvtext += ',';
				else csvtext += '\n';
			}
		}
		var sw = StageProxy.width()-2;
		var sh = StageProxy.height()-2;
		var maxheight = sh-40-20-20-40;
		Dialog.create({
			size: "600x"+maxheight,
			title: Lang.lookup("Order CSV Output"),
			content: classes.dialogs.CopyPaste,
			init: {
				text: csvtext
			},
			owner: this,
			options: [{
				label: Lang.lookup("Close")
			}]
		});
	}
	
	function getLogFile (obj) {
		_panel.screen();
		Auth.send(this, onLogData, {
			action: "get_log_file",
			orderid: obj.orderid
		});
	}
	function onLogData (success, data) {
		_panel.screen(false);
		var sw = StageProxy.width()-2;
		var sh = StageProxy.height()-2;
		var maxheight = sh-40-20-20-40;
		Dialog.create({
			size: "600x"+maxheight,
			title: Lang.lookup("Order Raw Log File"),
			content: classes.dialogs.CopyPaste,
			init: {
				csv: false,
				text: data || Lang.lookup("No Log Data Available")
			},
			owner: this,
			options: [{
				label: Lang.lookup("Close")
			}]
		});
	}
	
	function deleteClick (obj) {
		Dialog.create({
			size: "420x*",
			title: Lang.lookup("Delete Set Confirmation"),
			content: Lang.lookup("Delete Set Confirmation Description"),
			owner: this,
			options: [{
				label: Lang.lookup("Yes Delete"),
				func: deleteConfirm,
				param: obj
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	function deleteConfirm (obj) {
		_panel.screen();
		Auth.send(this, onOrderDelete, {
			action: "delete_order",
			timestamp: obj.timestamp,
			orderid: obj.orderid
		});
	}
	function onOrderDelete () {
		loadOrderData();
	}

	function searchClick () {
		Dialog.create({
			size: "600x*",
			title: Lang.lookup("Order Search"),
			content: classes.dialogs.OrderSearch,
			init: {
				range: _search_range,
				type: _search_type,
				orderid: _search_orderid,
				setid: _search_setid,
				name: _search_name,
				email: _search_email
			},
			owner: this,
			options: [{
				label: Lang.lookup("Search"),
				func: performSearch
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	function performSearch () {
		/*var tabdata = _panel.tabdata();
			tabdata[0].label = "Search Results";
		_panel.tabdata(tabdata);
		SiteBar.register(null, _panel.tabdata(), true);
		var xhtml = Lang.lookup("orders") +  " » " + _panel.tabdata()[0].label
		Admin.title(xhtml);*/
		// change tab label here to Lang.lookup["Search Results"]
		var editor = Dialog.last().classobj;
		_search_range = editor.range();
		_search_type = editor.type();
		_search_orderid = editor.orderid();
		_search_setid = editor.setid();
		_search_name = editor.name();
		_search_email = editor.email();
		loadOrderData();
	}
	function loadOrderData () {
		_panel.screen(true);
		//console.log(_search_range, _search_type, _search_orderid, _search_setid, _search_name, _search_email);
		Auth.send(this, onDataLoaded, {
			action: "order_search",
			date_start: _search_range.start,
			date_end: _search_range.end,
			payment_type: _search_type,
			orderid: _search_orderid,
			setid: _search_setid,
			full_name: _search_name,
			email_address: _search_email
		});
	}
	function onDataLoaded (success, data) {
		/*
			store everything as rows and columns
			*/
		_ingest = [];
		/*
			parse it all out
			*/
		if (data) {
			var lines = data=="" ? [] : data.split("\n");
			lines.reverse();
			for (var i=0; i<lines.length; ++i) {
				var line = lines[i];
				var values = line.split("\t");
				var obj = new Object();
				obj.index = i;
				for (var j=0; j<values.length; ++j) {
					var value = values[j];
					var column_id = _column_ids[j];
					obj[column_id] = value || "";
				}
				_ingest.push(obj);
			}
			//_ingest.reverse(); // newest first
		}
		/* manage the tab panel
			*/
		_panel.screen(false);
		/* clear the table, add new rows, then redraw
			*/
		_table.clear();
		_table.rows.add(_ingest);
		_table.draw(false);
		/* trigger change event if neccessary
			*/
		if (_trigger_change_event) {
			_trigger_change_event = false;
			_instance.dispatch("onChanged");
		}
	}
	
	function render () {
		
		var today = new Date();
			var year = today.getFullYear();
			var month = today.getMonth();
			var day = today.getDate();
		var todayclean = new Date(year, month, day+1, 0, 0, 0, 0);
			var year = todayclean.getFullYear();
			var month = todayclean.getMonth();
			var day = todayclean.getDate();
		_search_range.end = year + "/" + (month+1) + "/" + day;
		var monthago = new Date(year, month, day-30, 0, 0, 0, 0);
			var year = monthago.getFullYear();
			var month = monthago.getMonth();
			var day = monthago.getDate();
		_search_range.start = (year) + "/" + (month+1) + "/" + day;
		
		var parent = _panel.body();
		var xhtml = '';
			xhtml += '<div id="' + _uniquid + '" class="TablePanel">';
			xhtml += 	'<div class="Inner">';
			xhtml += 		'<div class="Options">';
			xhtml += 			'<div class="Button Search"><span class="glyphicon glyphicon-search" aria-hidden="true"></span> ' + Lang.lookup("Search") + '</div>';
			xhtml += 			'<div class="Button Export Secondary"><span class="glyphicon glyphicon-share-alt" aria-hidden="true"></span> ' + Lang.lookup("Export Data as CSV") + '</div>';
			xhtml += 			'<div class="Clear"></div>';
			xhtml += 		'</div>';
			xhtml += 		'<table class="table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Clear"></div>';
			xhtml += '</div>';
		parent.html(xhtml);
		
		_obj_search = parent.find("#" + _uniquid + " .Search");
		_obj_search.click(searchClick);
		_obj_export = parent.find("#" + _uniquid + " .Export");
		_obj_export.click(exportClick);
		
		/* start up our dataset
			*/
		loadOrderData();
		
		/* create the datatable
			*/
		_table = $('#' + _uniquid + " table").DataTable( {
			stateSave: true,
			stateSaveCallback: function(settings,data) {
				localStorage.setItem( _uniquid, JSON.stringify(data) )
			},
			stateLoadCallback: function(settings) {
				return JSON.parse( localStorage.getItem( _uniquid ) )
			},
			language: {
				emptyTable: Lang.lookup("No Orders Available")
			},
			rowReorder: false,
			searching: true,
			order: [[ 2, "desc" ]],
			paging: true,
			responsive: {
				details: false
			},
			select: false,
			data: [],
			columns: [
				{
					title: Lang.lookup("Order ID"),
					data: "orderid",
					width: 40,
					render: function ( data, type, row ) {
						return '<a title="' + Lang.lookup("View Invoice") + '" href="' + Auth.basepath() + Auth.indexpath() + "?/order/" + data + "/invoice/" + md5(row.email_address) + "/" + '" target="_blank">' + data + '</a>';
					},
					responsivePriority: 1
				},{
					title: Lang.lookup("Set ID"),
					data: "setid",
					width: 40,
					render: function ( data, type, row ) {
						return '<a href="' + Auth.basepath() + Auth.indexpath() + "?/set/" + data + '/" target="_blank" title="' + Lang.lookup("Launch Set") + '">' + data + '</a>';
					}
				},{
					title: Lang.lookup("Date"),
					data: "timestamp",
					type: "num",
					render: function ( data, type, row ) {
						data = Number(data);
						if ( type === 'display' || type === 'filter' ) {
							var d = new Date( data );
							return d.toLocaleDateString("en-US");
						}
						return data;
					}
				},{
					title: '<div style="text-align:center" class="DragIcon"><span class="glyphicon glyphicon-usd" aria-hidden="true"></span></div>',
					data: "payment_type",
					width: 24,
					orderable: false,
					render: function ( data, type, row ) {
						if (data=="offline") {
							return '<div style="text-align:center" class="DragIcon"><a title="Payment and receipt details" class="glyphicon glyphicon-envelope" aria-hidden="true"></a></div>';
						} else if (data=="paypal") {
							return '<div style="text-align:center" class="DragIcon"><a title="' + Lang.lookup("View Raw Payment Log") + '" class="glyphicon glyphicon-shopping-cart" aria-hidden="true"></a></div>';
						} else if (data=="stripe") {
							return '<div style="text-align:center" class="DragIcon"><a title="' + Lang.lookup("View Raw Payment Log") + '" class="glyphicon glyphicon-credit-card" aria-hidden="true"></a></div>';
						}
					}	
				},{
					title: '<div style="text-align:center" class="DragIcon"><span class="glyphicon glyphicon-send" aria-hidden="true"></span></div>',
					data: "shipping_type",
					width: 24,
					orderable: false,
					render: function ( data, type, row ) {
						if (data=="ship") {
							return '<div style="text-align:center" class="DragIcon"><span class="glyphicon glyphicon-ok" aria-hidden="true"></span></div>';
						} else {
							return '';
						}
					}	
				},{
					title: '<div style="text-align:center" class="DragIcon"><span class="glyphicon glyphicon-globe" aria-hidden="true"></span></div>',
					data: "country",
					width: 40,
					render: function ( data, type, row ) {
						var value = new Array();
						if (data!=""&&data!=undefined) value.push(data);
						if (row.state!=""&&row.state!=undefined) value.push(row.state);
						return value.join("-");
					}	
				},{
					title: Lang.lookup("Gross"),
					data: "gross",
					type: "num",
					width: 60,
					render: function ( data, type, row ) {
						var value = parseFloat(data);
						if (isNaN(value)) value = 0;
						if ( type === 'display' || type === 'filter' ) {
							return Func.toFixed(value, 2);
						}
						return value;
					}	
				},{
					title: Lang.lookup("Net"),
					data: "subtotal",
					type: "num",
					width: 60,
					render: function ( data, type, row ) {
						var subtotal = parseFloat(data);
						if (isNaN(subtotal)) subtotal = 0;
						var discount = parseFloat(row.discount);
							if (!isNaN(discount)) subtotal -= discount;
						if ( type === 'display' || type === 'filter' ) {
							return Func.toFixed(subtotal, 2);
						}
						return subtotal;
					}	
				},{
					title: Lang.lookup("Purchaser"),
					data: "email_address",
					render: function ( data, type, row ) {
						return '<a href="mailto:' + data + '" target="_blank" title="' + Lang.lookup("Email User") + '">' + row.full_name + '</a>';
					}
				},{
					title: "Payment status",
					data: "payment_status",
					render: $.fn.dataTable.render.text()
				},{
					title: Lang.lookup("Phone Number"),
					data: "phone_number"
				},{
					title: Lang.lookup("Actions"),
					data: "orderid",
					orderable: false,
					render: function ( data, type, row ) {
						var xhtml = '';
							xhtml += '<a data-suid="' + data + '" data-action="del">Delete</a> / ';
							xhtml += '<a data-suid="' + data + '" data-action="output">Output</a> / ';
							xhtml += '<a data-suid="' + data + '" data-action="receipts">Retry failed receipts</a>';
							if (row.payment_type=="offline" && row.payment_status=="pending") xhtml += ' / <a data-suid="' + data + '" data-action="paid">Record manual payment</a>';
						return xhtml;
					},
					responsivePriority: 2
				}
			],
			columnDefs: [{
				targets: 3,
				createdCell: function (td, cellData, rowData, row, col) {
					var html = $(td);
					var obj = html.find("a");
					obj.click(function (e) {
						getLogFile(rowData);
						e.preventDefault();
						return false;
					});
				}
			},{
				targets: -1,
				createdCell: function (td, cellData, rowData, row, col) {
					var html = $(td);
					var obj = html.find("a");
					obj.click(function (e) {
						action($(this).data("action"), rowData);
						e.preventDefault();
						return false;
					});
				}
			}]
		});
	}
	
	/* public methods
		*/
		
	this.option = function (key) {
		doOption(key);
	};
	this.panel = function (obj) {
		_panel = obj;
	};
	this.controller = function (obj) {
		_controller = obj;
	};
	this.destroy = function () {
		$('#' + _uniquid).find("a").off();
		_obj_search.off();
		_obj_export.off();
		_table.destroy(true);
	};
	this.initialize = function () {
		Admin = classes.Admin;
		Auth = classes.data.Auth;
		Lang = classes.data.Lang;
		Dialog = classes.components.Dialog;
		Func = classes.helpers.Func;
		SetList = classes.components.SetList;
		SiteBar = classes.components.SiteBar;
		render();
	};
	
};

classes.panels.Orders.prototype = new EventDispatcher();

;
classes.panels.CategorySet = function () {
	
	/* "imported" classes
		*/
		
	var Admin;
	var SetList;
	var SiteBar;
	var Func;
	var Dialog;
	var Lang;
	var Auth;
	
	/* private properites
		*/
		
	var _instance = 			this;
	var _panel = 				null;
	var _controller = 			null;
	var _suid = 				"";
	var _uniquid = 				"FO" + classes.helpers.Func.uniquid();
	
	var _selected = 			[];
	var category_rows = 		[];
	var category_lookup = 		{};
	var categories_hash = 		null;
	var image_rows = 			[];
	var image_lookup = 			{};
	var _trigger_image_reload = false;
	
	var _obj_right = 			null;
	var _obj_delete = 			null;
	var _category_table = 		null;
	var _editor = 				null;

	/* private methods
		*/
	
	function move (dir, ifrom, ito) {
		_panel.screen(true);
		Auth.send(this, onCategories, {
			name: "category",
			puid: _suid,
			action: "set_reindex",
			from: ifrom,
			to: ito
		});
	}
	
	function deleteAssets () {
		Dialog.create({
			size: "520x*",
			title: Lang.lookup("delete_files_confirmation"),
			content: Lang.lookup("delete_files_confirmation_description"),
			owner: this,
			options: [{
				label: Lang.lookup("yes_delete"),
				func: deleteAssetsConfirm
			},{
				label: Lang.lookup("cancel")
			}]
		});
	}
	function deleteAssetsConfirm () {
		_panel.screen(true);
		var files = [];
		var group = image_lookup[_selected[0].hash];
		if (!group) {
			onDeleteAssets();
			return;
		}
		for (var i=0; i<group.length; ++i) {
			files.push(group[i].filename);
		}
		files = files.join(",");
		Auth.send(this, onDeleteAssets, {
			name: "page",
			suid: _suid,
			action: "image_delete",
			files: files
		});
	}
	function onDeleteAssets (success, data) {
		Auth.send(this, onDeleteCategory, {
			action: "set_delete",
			suid: _selected[0].hash,
			puid: _suid,
			name: "category"
		});
		_selected = [];
	}
	function onDeleteCategory (success, data) {
		_panel.screen(false);
		_editor.reload();
	}
	
	/* --- Datatable Selection / Functions --- */
	function syncSelection () {
		for (var i=0; i<category_rows.length; ++i) {
			var row = _category_table.row(i);
			var node = $(row.node());
			var data = row.data();
			for (var j=0; j<_selected.length; ++j) {
				if ( data.hash == _selected[j].hash ) {
					if (node.hasClass("selected")==false) {
						row.select();
						change();
						break;
					}
				}
			}
		}
	}
	function change () {
		syncSelection();
		_obj_delete.addClass("Disabled").off();
		if (_selected.length>0) {
			_obj_delete.removeClass("Disabled").click(deleteAssets);
		}
		_editor.deselect(false);
		_editor.refilter(true);
	}
	function addByHash (hash) {
		var doadd = true;
		var obj;
		for (var i=0; i<category_rows.length; ++i) {
			if (category_rows[i].hash==hash) {
				obj = category_rows[i];
				break;
			}
		}
		for (var i=0; i<_selected.length; ++i) {
			if (_selected[i].hash==hash) {
				_selected[i] = obj; // update
				doadd = false
				break;
			}
		}
		if (doadd) {
			_selected.push(obj);
			change();
		}
	}
	function removeByHash (hash) {
		for (var i=0; i<_selected.length; ++i) {
			if (_selected[i].hash==hash) {
				_selected.splice(i, 1);
				change();
				break;
			}
		}
	}
	
	function onAssetData () {
		image_lookup = new Object();
		var images = _editor.getIngest(true);
		for (var i=0; i<images.length; ++i) {
			var obj = images[i];
			var hash = obj.media_uri;
			if (image_lookup[hash]==undefined) image_lookup[hash] = new Array();
			image_lookup[hash].push(obj);
		}
		_panel.screen(true);
		Auth.send(this, onCategories, {
			puid: _suid,
			name: "category",
			action: "set_list"
		});
	}
	
	function parseCategories (success, data) {
		/*
			store everything as rows and columns
			*/
		category_rows = new Array();
		/*
			parse it all out
			*/
		if (data) {
			var lines = data=="" ? [] : data.split("\n");
			var column_ids = ["hash", "label"];
			for (var i=0; i<lines.length; ++i) {
				var line = lines[i];
				var values = line.split("\t");
				var obj = new Object();
				obj.index = i;
				for (var j=0; j<values.length; ++j) {
					var value = values[j];
					var column_id = column_ids[j];
					obj[column_id] = value;
				}
				obj.count = image_lookup[obj.hash] ? image_lookup[obj.hash].length : 0;
				category_rows.push(obj);
			}
		}
	}
	
	function onCategories (success, data) {
		/*
			re-populate the grid
			*/
		_panel.screen(false);
		/*
			parse it all out
			*/
		parseCategories(success, data);
		/* clear the table, add new rows, then redraw
			*/
		_category_table.clear();
		_category_table.rows.add(category_rows);
		_category_table.draw(false);
		/*
			setup the selection
			*/
		change();
	}
	
	function filter (obj) {
		if (_selected.length==1) {
			if (obj.media_uri==_selected[0].hash) {
				return obj;
			}
		}
		return false;
	}
	
	function render () {
		
		var parent = _panel.body();
		var xhtml = '';
			xhtml += 	'<div id="' + _uniquid + '" class="StatsPanel SetPanel">';
			xhtml += 		'<div class="Third">';
			xhtml += 			'<div class="TablePanel">';
			xhtml += 				'<div class="Inner">';
			xhtml += 					'<div class="Options">';
			xhtml += 						'<div class="Button Delete Disabled"><span class="glyphicon glyphicon-trash" aria-hidden="true"></span> ' + Lang.lookup("Delete Selected") + '</div>';
			xhtml += 						'<div class="Clear"></div>';
			xhtml += 					'</div>';
			xhtml += 				'</div>';
			xhtml += 				'<table class="table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 			'</div>';
			xhtml += 			'<div class="Clear"></div>';
			xhtml += 		'</div>';
			xhtml += 		'<div class="TwoThirds"></div>';
			xhtml += 		'<div class="Clear"></div>';
			xhtml += 	'</div>';
		parent.html(xhtml);
		
		_obj_delete = parent.find("#" + _uniquid + " .Delete");
		_obj_right = $('#' + _uniquid + " .TwoThirds");
		
		_editor = new classes.panels.AssetLibrary();
		_editor.filter(filter);
		_editor.paging(true);
		_editor.parent(_obj_right);
		_editor.panel(_panel);
		_editor.suid(_suid);
		_editor.name("page");
		_editor.display("category");
		_editor.uniquid("page-image-list-"+_suid);
		_editor.curated(true);
		_editor.addEventListener("onAssetData", onAssetData);
		_editor.key("image");
		_editor.initialize();
		
		/* create the datatable
			*/
		_category_table = $('#' + _uniquid + " .Third table").DataTable( {
			rowReorder: {
				update: false,
				dataSrc: 'index'
			},
			language: {
				emptyTable: Lang.lookup("No Categories Uploaded")
			},
			searching: false,
			ordering: false,
			paging: true,
			info: false,
			responsive: {
				details: false
			},
			select: true,
			data: [],
			columns: [
				{
					title: "",
					data: "index",
					width: 30,
					render: function ( data, type, row ) {
						return '<div style="text-align:center;cursor:pointer" class="DragIcon"><span class="glyphicon glyphicon-option-horizontal" aria-hidden="true"></span></div>';
					}
				},{
					title: Lang.lookup("Category"),
					data: "label",
					render: function ( data, type, row ) {
						var xhtml = '';
						if ( row.count==0 ) {
							xhtml += '<span style="color:#ccc;font-style:italic;text-decoration:line-through;">';
						}
							xhtml += data;
						if ( row.count==0 ) {
							xhtml += '</span>';
						}
						return xhtml;
					}
				},{
					title: Lang.lookup("Images"),
					type: "num",
					data: "count"
				}
			]
		});
		_category_table.on( 'row-reorder', function ( e, diff, edit ) {
			var trigger = edit.triggerRow[0][0];
			for (var i=0; i<diff.length; ++i) {
				var obj = diff[i];
				if (trigger==obj.oldPosition) {
					move(0, obj.oldPosition, obj.newPosition);
					break;
				}
			}
		});
		_category_table.on( 'select', function ( e, dt, type, indexes ) {
			if ( type === 'row' ) {
				var hash = _category_table.rows( indexes ).data()[0].hash;
				if (hash=="") return;
				addByHash(hash);
			}
		});
		_category_table.on( 'deselect', function ( e, dt, type, indexes ) {
			if ( type === 'row' ) {
				var hash = _category_table.rows( indexes ).data()[0].hash;
				if (hash=="") return;
				removeByHash(hash);
			}
		});
		
	}
	
	/* public methods
		*/
		
	this.suid = function (str) {
		if (str) {
			_suid = str;
		}
		return _suid;
	};
	this.option = function (key) {
		doOption(key);
	};
	this.panel = function (obj) {
		_panel = obj;
	};
	this.controller = function (obj) {
		_controller = obj;
	};
	this.destroy = function () {
		_obj_delete.off();
		_editor.removeEventListener("onAssetData", onAssetData);
		_editor.destroy();
		_category_table.off('row-reorder');
		_category_table.off('select');
		_category_table.off('deselect');
		_category_table.destroy(true);
	};
	this.initialize = function (obj) {
		Admin = classes.Admin;
		Auth = classes.data.Auth;
		Lang = classes.data.Lang;
		Dialog = classes.components.Dialog;
		Func = classes.helpers.Func;
		SetList = classes.components.SetList;
		SiteBar = classes.components.SiteBar;
		for (var prop in obj) {
			this[prop](obj[prop]);
		}
		render();
	};
	
};

classes.panels.CategorySet.prototype = new EventDispatcher();
;

/*jslint browser: true, continue: true, eqeq: true, evil: true, plusplus: true, sloppy: true, vars: true, white: true */

classes.panels.Products = function () {
	
	/* "imported" classes
		*/
		
	var Admin;
	var Auth;
	var SetList;
	var Func;
	var Dialog;
	var Lang;
	
	/* private properites
		*/
		
	var _instance = 			this;
	var _setlist = 				null;
	var _panel = 				null;
	var _controller = 			null;
	var _state = 				[];
	
	var _table = 				null;
	var _obj_create = 			null;
	var _obj_back = 			null;
	var _uniquid = 				"FO" + classes.helpers.Func.uniquid();
	
	/* private methods
		*/
		
	function action (key, obj) {
		switch (key) {
			case "edit" :
				editClick(obj);
				break;
			case "del" :
				deleteClick(obj);
				break;
			case "prints" :
				printsClick(obj);
				break;
		}
	}
	
	function backClick () {
		Admin.state(null, _state[0]);
	}
	
	function printsClick (obj) {
		Admin.state(null, _state[0] + "/" + _state[1] + "/" + "lineitem" + "/" + obj.suid);
	}

	function createConfirm () {
		var editor = Dialog.last().classobj;
		_setlist.createObject({
			label: editor.label(),
			filename: editor.filename(),
			price: editor.price(),
			shipping: editor.shipping(),
			description: editor.description()
		});
	}
	function createClick () {
		Dialog.create({
			size: "640x*",
			title: Lang.lookup("Create Product"),
			content: classes.dialogs.ProductEditor,
			init: {
			},
			owner: this,
			options: [{
				label: Lang.lookup("Save"),
				func: createConfirm
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	
	function editConfirm (obj) {
		var editor = Dialog.last().classobj;
		_setlist.updateObject({
			label: editor.label(),
			filename: editor.filename(),
			price: editor.price(),
			shipping: editor.shipping(),
			description: editor.description()
		}, obj.suid);
	}
	function editClick (obj) {
		Dialog.create({
			size: "640x*",
			title: Lang.lookup("Edit Product"),
			content: classes.dialogs.ProductEditor,
			init: {
				label: obj.label,
				filename: obj.filename,
				price: obj.price,
				shipping: obj.shipping,
				description: obj.description
			},
			options: [{
				label: Lang.lookup("Save Changes"),
				func: editConfirm,
				param: obj
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	
	function deleteClick (obj) {
		Dialog.create({
			size: "420x*",
			title: Lang.lookup("Delete Set Confirmation"),
			content: Lang.lookup("Delete Set Confirmation Description"),
			owner: this,
			options: [{
				label: Lang.lookup("Yes Delete"),
				func: deleteConfirm,
				param: obj
			},{
				label: Lang.lookup("Cancel")
			}]
		});
	}
	function deleteConfirm (obj) {
		_setlist.deleteSet(obj.suid);
	}

	function onDataLoaded () {
		/* manage the tab panel
			*/
		_panel.screen(false);
		/* clear the table, add new rows, then redraw
			*/
		_table.clear();
		_table.rows.add(_setlist.ingest());
		_table.draw(false);
	}
	function onStartLoad () {
		_panel.screen(true);
	}

	function render () {
	}
	
	function draw () {
		
		var parent = _panel.body();
		var xhtml = '';
			xhtml += '<div id="' + _uniquid + '" class="TablePanel">';
			xhtml += 	'<div class="Inner">';
			xhtml += 		'<div class="Options">';
			xhtml += 			'<div class="Button Secondary Back"><span class="glyphicon glyphicon-menu-left" aria-hidden="true"></span></div>';
			xhtml += 			'<div class="Button Create"><span class="glyphicon glyphicon-plus" aria-hidden="true"></span> ' + Lang.lookup("Create New Product") + '</div>';
			xhtml += 			'<div class="Clear"></div>';
			xhtml += 		'</div>';
			xhtml += 		'<table class="AssetTableCurated table table-striped table-bordered" width="100%" cellspacing="0"></table>';
			xhtml += 	'</div>';
			xhtml += 	'<div class="Clear"></div>';
			xhtml += '</div>';
		parent.html(xhtml);
		
		_obj_back = parent.find("#" + _uniquid + " .Back");
		_obj_create = parent.find("#" + _uniquid + " .Create");
		_obj_back.click(backClick);
		_obj_create.click(createClick);
		
		/* create the datatable
			*/
		_table = $('#' + _uniquid + " table").DataTable( {
			language: {
				emptyTable: Lang.lookup("No Products Created")
			},
			rowReorder: {
				update: false,
				dataSrc: 'index'
			},
			searching: false,
			paging: false,
			ordering: false,
			responsive: {
				details: false
			},
			select: false,
			data: [],
			columns: [
				{
					title: '',
					data: "index",
					width: 30,
					render: function ( data, type, row ) {
						return '<div style="text-align:center;cursor:pointer" class="DragIcon"><span class="glyphicon glyphicon-option-horizontal" aria-hidden="true"></span></div>';
					}
				},{
					title: Lang.lookup("Photo"),
					data: "filename",
					width: 100,
					render: function ( data, type, row ) {
						var ext = data.split(".").pop().toLowerCase();
						var group = data.split("/");
							group = group.pop();
							group = "product" + ":" + group;
						var xhtml = '<div style="text-align:center">';
						var URI = Auth.basepath() + NAMESPACE + "-resample.php?q=";
						var query = "";
							query += group + ":"; // the folder:file combo
							query += 100 + ":"; // the width
							query += 100 + ":"; // the height
							query += 1 + ":::1"; // the thumbnail it
						if (data=="") {
							URI = Func.getEmptyImgSrc();
							query = "";
						}
							xhtml += '<div id="file-' + md5(data) + '" class="ImageObject">';
							xhtml += 	'<img src="' + URI + query + '" width="100" height="100" />';
							xhtml += '</div>';
							xhtml += '</div>';
						return xhtml;
					}
				},{
					title: Lang.lookup("Description"),
					data: "label",
					render: function ( data, type, row ) {
						data = data.split(" ").join("&nbsp;");
						if ( data=="" ) {
							data = '<i>' + Lang.lookup("Untitled") + "</i>";
						}
						if ( type === 'display' || type === 'filter' ) {
							var xhtml = '';
								xhtml += 	'<a title="Edit">' + data + '</a>';
							if ( row.description!=undefined && row.description!="" ) {
								xhtml += 	'<div class="AssetLabelDesc">';
								xhtml += 	row.description;
								xhtml += 	'</div>';
							}
							return xhtml;
						}
						return data;
					},
					responsivePriority: 1
				},{
					title: Lang.lookup("Price"),
					data: "price",
					type: "num",
					width: 60,
					render: function ( data, type, row ) {
						var value = parseFloat(data);
						if (isNaN(value)) value = 0;
						if ( type === 'display' || type === 'filter' ) {
							return Func.toFixed(value, 2);
						}
						return value;
					}
				},{
					title: Lang.lookup("Actions"),
					data: "suid",
					render: function ( data, type, row ) {
						var xhtml = '';
							xhtml += '<a data-suid="' + data + '" data-action="del">Delete</a> / ';
							xhtml += '<a data-suid="' + data + '" data-action="prints">Prints & Formats</a>';
						return xhtml;
					},
					responsivePriority: 2
				}
			],
			columnDefs: [{
				targets: 2,
				createdCell: function (td, cellData, rowData, row, col) {
					var html = $(td);
					var obj = html.find("a");
					obj.click(function (e) {
						editClick(rowData);
						e.preventDefault();
						return false;
					});
				}
			},{
				targets: -1,
				createdCell: function (td, cellData, rowData, row, col) {
					var html = $(td);
					var obj = html.find("a");
					obj.click(function (e) {
						action($(this).data("action"), rowData);
						e.preventDefault();
						return false;
					});
				}
			}]
		});
		_table.on( 'row-reorder', function ( e, diff, edit ) {
			var trigger = edit.triggerRow[0][0];
			for (var i=0; i<diff.length; ++i) {
				var obj = diff[i];
				if (trigger==obj.oldPosition) {
					var data = _setlist.ingest()[trigger];
					_setlist.reIndex(obj.oldPosition, obj.newPosition, data.suid);
					break;
				}
			}
		});
		
		/* start up our dataset
			*/
		_setlist = new SetList();
		_setlist.name("product");
		_setlist.puid(_state[1]);
		_setlist.columms(["label", "filename", "price", "shipping", "description"]);
		_setlist.addEventListener("onStartLoad", onStartLoad);
		_setlist.addEventListener("onDataLoaded", onDataLoaded);
		_setlist.initialize();

	}
	
	/* public methods
		*/
		
	this.option = function (key) {
		doOption(key);
	};
	this.panel = function (obj) {
		_panel = obj;
	};
	this.controller = function (obj) {
		_controller = obj;
	};
	this.state = function (arr) {
		_state = arr;
		draw();
	};
	this.destroy = function () {
		$('#' + _uniquid).find("a").off();
		_obj_back.off();
		_obj_create.off();
		_table.off('row-reorder');
		_table.destroy(true);
		_setlist.removeEventListener("onStartLoad", onStartLoad);
		_setlist.removeEventListener("onDataLoaded", onDataLoaded);
	};
	this.initialize = function (obj) {
		Admin = classes.Admin;
		Auth = classes.data.Auth;
		Lang = classes.data.Lang;
		Dialog = classes.components.Dialog;
		Func = classes.helpers.Func;
		SetList = classes.components.SetList;
		for (var prop in obj) {
			this[prop](obj[prop]);
		}
		render();
	};
	
};

